_CLAIM_DEFS: list[tuple[str, Any, str, str, Any]] = []


def _emit_claim_payload(
    claims: ClaimCollection,
    claim_id: str,
    payload,
    *,
    kind: str,
    subject: str,
    data: Any = None,
):
    return claims.claim(claim_id, payload, kind=kind, subject=subject, data=data)


def _claim_payload(
    claim_id: str,
    payload,
    *,
    kind: str,
    subject: str,
    data: Any = None,
):
    _CLAIM_DEFS.append((claim_id, payload, kind, subject, data))
    return payload


def _kq_simple_foi_link(label: str):
    return author.anc_h(label, _KQ_SIMPLE_FOI_URL + label)


def _kq_simple_foi_link_for_sug(sug_text: str):
    kq_type = kqst.canonical_special_kq_type_from_name_and_sug(
        kqst.UNIFIED_SPECIAL_KQ_TEMPLATE_NAME,
        sug_text,
    )
    intro_label = _KQ_SIMPLE_FOI_INTRO_BY_SPECIAL_KQ_TYPE[kq_type]
    return _kq_simple_foi_link(intro_label)


