def emit_claims(*, claims: ClaimCollection):
    """Emit mp_cmn claims into an explicit claims collection."""
    for claim_id, payload, kind, subject, data in _CLAIM_DEFS:
        _emit_claim_payload(
            claims,
            claim_id,
            payload,
            kind=kind,
            subject=subject,
            data=data,
        )


def s_file_naming():
    return [
        author.heading_level_2("File naming"),
        author.para(
            [
                "File names (e.g. ",
                mb_html.code("A1-Genesis.json"),
                ") start with two characters that identify the book"
                " (in the \u201c24 books\u201d sense) and provide a standard ordering."
                " The first character (",
                mb_html.code("sec_char"),
                ") comes from the set ABCDEF and indicates the section of Tanakh."
                " The second character (",
                mb_html.code("book24_char"),
                ") comes from the set 12345AC and indicates the book within that section.",
            ]
        ),
        author.para(
            [
                "Files are named ",
                mb_html.code("{sec_char}{book24_char}-{EnglishName}.json"),
                ":",
            ]
        ),
        author.std_table(_FILE_NAMING_ROWS, arg_to_troh=["Prefix", "Section", "Books"]),
        author.para(
            [
                "When ",
                mb_html.code("book24_char"),
                " is A or C,"
                " the file is for a book24 with sub-books"
                " (e.g. BA-Samuel has sub-books 1 Samuel and 2 Samuel)."
                " The letter B is not used in order to keep compatibility"
                " with a set of codes used for the 39-book system.",
            ]
        ),
    ]
